<?php
declare(strict_types=1);

namespace KhoNpl\Services;

use KhoNpl\Core\Database;
use KhoNpl\Core\HttpException;

final class TransactionService
{
    public function __construct(private readonly \PDO $db, private readonly AuthService $auth, private readonly InventoryService $inventory) {}

    private function audit(string $email, string $action, string $type, string $id, string $requestId = '', string $reason = '', string $old = '', string $new = ''): void
    {
        $this->db->prepare('INSERT INTO audit_logs(user_email,action,object_type,object_id,old_value,new_value,reason,client_request_id,environment) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$email,$action,$type,$id,$old,$new,$reason,$requestId,getenv('KHO_ENV') ?: 'THU_NGHIEM']);
    }

    private function nextCode(string $type, string $date): string
    {
        $prefix = ['RECEIPT'=>'PN','ISSUE'=>'PX','RETURN'=>'TL','ADJUSTMENT'=>'DC','REVERSAL'=>'RV'][$type] ?? 'DC';
        $st=$this->db->prepare('INSERT INTO document_sequences(doc_type,doc_date,last_no) VALUES(?,?,1) ON DUPLICATE KEY UPDATE last_no=last_no+1'); $st->execute([$type,$date]);
        $st=$this->db->prepare('SELECT last_no FROM document_sequences WHERE doc_type=? AND doc_date=? FOR UPDATE'); $st->execute([$type,$date]); $no=(int)$st->fetchColumn();
        return $prefix . date('ymd', strtotime($date)) . '-' . str_pad((string)$no,3,'0',STR_PAD_LEFT);
    }

    private function beginIdem(string $id, string $operation, string $email, array $payload): ?array
    {
        $st=$this->db->prepare('SELECT status,response_json FROM idempotency_requests WHERE client_request_id=? FOR UPDATE'); $st->execute([$id]); $old=$st->fetch();
        if ($old && $old['status']==='DONE') return json_decode((string)$old['response_json'], true) ?: null;
        if (!$old) $this->db->prepare('INSERT INTO idempotency_requests(client_request_id,operation,user_email,request_hash,status) VALUES(?,?,?,?,?)')->execute([$id,$operation,$email,json_hash($payload),'PROCESSING']);
        return null;
    }

    private function finishIdem(string $id, array $response): void
    { $this->db->prepare('UPDATE idempotency_requests SET status="DONE",response_json=?,completed_at=NOW() WHERE client_request_id=?')->execute([json_encode($response,JSON_UNESCAPED_UNICODE),$id]); }

    public function receipt(string $email, array $p): array
    {
        $this->auth->require($email,['WAREHOUSE']); $supplierId=s($p['supplierId']??''); $date=date_ymd($p['receiptDate']??null); $client=s($p['clientRequestId']??'') ?: uuid_id('REQ'); $lines=array_values(array_filter((array)($p['lines']??[]),fn($x)=>n($x['deliveredQty']??0)>0||n($x['acceptedQty']??0)>0));
        require_true($supplierId!=='','Thiếu NCC'); require_true((bool)$lines,'Chưa nhập dòng hàng nhận');
        return Database::transaction(function() use($email,$supplierId,$date,$client,$lines,$p) {
            $idem=$this->beginIdem($client,'RECEIPT_POST',$email,$p); if($idem) return $idem;
            $st=$this->db->prepare('SELECT * FROM suppliers WHERE supplier_id=? AND is_active=1'); $st->execute([$supplierId]); $supplier=$st->fetch(); require_true((bool)$supplier,'NCC không có trong danh mục','SUPPLIER_NOT_FOUND',404);
            $seen=[]; $sources=[]; foreach($lines as $line){$key=s($line['prRefKey']??''); require_true($key!==''&&!isset($seen[$key]),'Dòng ĐNMH bị lặp trong cùng phiếu','BLOCK_DUPLICATE_PR_LINE');$seen[$key]=1;$sources[]=$key;}
            $in=implode(',',array_fill(0,count($sources),'?')); $st=$this->db->prepare("SELECT * FROM purchase_request_lines WHERE pr_ref_key IN ($in) FOR UPDATE"); $st->execute($sources); $rows=[]; foreach($st->fetchAll() as $r)$rows[$r['pr_ref_key']]=$r; require_true(count($rows)===count($sources),'Có dòng ĐNMH không tồn tại','PR_LINE_NOT_FOUND',404);
            $receiptId=uuid_id('REC'); $code=$this->nextCode('RECEIPT',$date); $this->db->prepare('INSERT INTO receipts(receipt_id,receipt_code,receipt_date,supplier_id,supplier_name_snapshot,delivery_note_no,delivered_by,status,price_status,received_by,posted_by,posted_at,client_request_id,note) VALUES(?,?,?,?,?,?,?,?,?,?,?,NOW(),?,?)')->execute([$receiptId,$code,$date,$supplierId,$supplier['supplier_display_name'],$p['deliveryNoteNo']??'',$p['deliveredBy']??'','POSTED','PROVISIONAL',$email,$email,$client,$p['note']??'']);
            $resultLines=[];
            foreach($lines as $line){$src=$rows[s($line['prRefKey'])]; require_true($src['supplier_id']===$supplierId,'Dòng ĐNMH không thuộc NCC đã chọn','PR_SUPPLIER_MISMATCH'); require_true(n($src['remaining_qty'])>0,'Dòng ĐNMH đã nhận đủ','PR_ALREADY_COMPLETE'); $del=n($line['deliveredQty']??0);$acc=n($line['acceptedQty']??0);$price=array_key_exists('actualUnitPrice',$line)&&$line['actualUnitPrice']!==''?n($line['actualUnitPrice']):n($src['estimated_unit_price']);$quality=s($line['qualityStatus']??'ACCEPTED')?:'ACCEPTED';$reject=max($del-$acc,0);$over=max($acc-n($src['remaining_qty']),0); require_true($del>=0&&$acc>=0&&$acc<=$del,'SL đạt không hợp lệ'); require_true($price>=0,'Đơn giá không hợp lệ'); require_true($over<=0||s($line['overReceiptReason']??''),'Nhận vượt nhưng thiếu lý do'); if($reject>0)require_true(in_array($quality,['PARTIAL_REJECT','REJECTED'],true),'Có hàng loại nhưng trạng thái chưa đúng'); if($acc===0&&$del>0)require_true($quality==='REJECTED','Không nhận hàng đạt phải đánh dấu REJECTED'); if($acc>0&&$reject>0)require_true($quality==='PARTIAL_REJECT','Có hàng đạt + hàng loại phải PARTIAL_REJECT');
                $lineId=uuid_id('RL');$amount=$acc*$price;$this->db->prepare('INSERT INTO receipt_lines(receipt_line_id,receipt_id,receipt_code,pr_ref_key,pr_code,order_code,execution_code,product_code,material_id,material_name_snapshot,uom_snapshot,ordered_qty,previous_received_qty,remaining_before_receipt,delivered_qty,accepted_qty,rejected_qty,expected_unit_price,actual_unit_price,management_amount,quality_status,over_receipt_qty,over_receipt_reason,item_class,lot_no,note) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$lineId,$receiptId,$code,$src['pr_ref_key'],$src['pr_code'],$src['order_code'],$src['execution_code'],$src['product_code'],$src['material_id'],$src['material_name'],$src['uom'],$src['ordered_qty'],$src['received_qty'],$src['remaining_qty'],$del,$acc,$reject,$src['estimated_unit_price'],$price,$amount,$quality,$over,$line['overReceiptReason']??'','STOCK',$line['lotNo']??'',$line['note']??'']);
                $newReceived=n($src['received_qty'])+$acc;$remaining=max(n($src['ordered_qty'])-$newReceived,0);$status=$newReceived>n($src['ordered_qty'])?'OVER_RECEIPT':($remaining<1e-9?'COMPLETE':'PARTIAL');$this->db->prepare('UPDATE purchase_request_lines SET received_qty=?,remaining_qty=?,line_status=? WHERE pr_ref_key=?')->execute([$newReceived,$remaining,$status,$src['pr_ref_key']]);
                if($acc>0){$m=$this->inventory->movement(['ledger_id'=>'LG-'.$lineId,'transaction_date'=>$date,'transaction_type'=>'NHAP_MUA','transaction_id'=>$receiptId,'transaction_line_id'=>$lineId,'document_code'=>$code,'material_id'=>$src['material_id'],'qty_in'=>$acc,'qty_out'=>0,'unit_cost'=>$price,'order_code'=>$src['order_code'],'execution_code'=>$src['execution_code'],'product_code'=>$src['product_code'],'supplier_id'=>$supplierId,'pr_code'=>$src['pr_code'],'created_by'=>$email,'client_request_id'=>$client]);}
                $resultLines[]=['receiptLineId'=>$lineId,'materialId'=>$src['material_id'],'acceptedQty'=>$acc];
            }
            $this->audit($email,'POST_RECEIPT','RECEIPT',$receiptId,$client,'POST hợp lệ','DRAFT','POSTED');$response=['receiptId'=>$receiptId,'receiptCode'=>$code,'clientRequestId'=>$client,'lineCount'=>count($resultLines),'lines'=>$resultLines];$this->finishIdem($client,$response);return $response;
        });
    }

    public function reservationContext(string $email, string $execution): array
    {
        $this->auth->require($email,['PROCUREMENT','PRODUCTION_MANAGER']); $execution=code($execution); require_true($execution!=='','Thiếu Mã BBSX/M/SH');
        $st=$this->db->prepare('SELECT d.* FROM dmsx_lines d JOIN active_bbsx a ON a.execution_code=d.execution_code AND a.product_code=d.product_code AND a.is_npl_tracking=1 WHERE d.execution_code=? AND d.gross_requirement_qty>0');$st->execute([$execution]);$groups=[];
        foreach($st->fetchAll() as $r){$key=$execution.'|'.code($r['product_code']).'|'.s($r['material_id']);if(!isset($groups[$key]))$groups[$key]=['requirementKey'=>$key,'sourceRequirementKey'=>'REQ|'.$key,'executionCode'=>$execution,'orderCode'=>code($r['order_code']),'productCode'=>code($r['product_code']),'materialId'=>s($r['material_id']),'materialName'=>s($r['material_name']),'uom'=>s($r['uom']),'requiredQty'=>0,'requiredDate'=>null,'sourceRows'=>[]];$groups[$key]['requiredQty']+=n($r['gross_requirement_qty']);$groups[$key]['sourceRows'][]=(string)$r['source_row_key'];foreach([$r['required_fabric_date'],$r['required_trim_date']] as $d){if($d&&(!$groups[$key]['requiredDate']||strtotime($d)<strtotime((string)$groups[$key]['requiredDate'])))$groups[$key]['requiredDate']=$d;}}
        require_true((bool)$groups,'Không có nhu cầu NPL đang theo dõi cho '.$execution,'NO_ACTIVE_REQUIREMENT');$totals=$this->inventory->reservationTotals();$contexts=[];
        foreach($groups as $key=>$g){$st=$this->db->prepare('SELECT * FROM reservations WHERE requirement_key=? AND status<>"CANCELLED"');$st->execute([$key]);$res=$st->fetch();$bal=$this->inventory->balance($g['materialId']);$total=n($totals[$g['materialId']]??0);$global=max($bal['qty']-$total,0);$issued=n($res['issued_qty']??0);$released=n($res['released_qty']??0);$current=n($res['remaining_reserved_qty']??0);$remaining=max($g['requiredQty']-$issued-$released,0);$mat=$this->db->prepare('SELECT COUNT(*) FROM materials WHERE material_id=?');$mat->execute([$g['materialId']]);$blocked=(int)$mat->fetchColumn()!==1;$contexts[]=array_merge($g,['reservationId'=>$res['reservation_id']??'','reservationStatus'=>$res['status']??'CHƯA GIỮ','issuedQty'=>$issued,'releasedQty'=>$released,'currentRemainingReservedQty'=>$current,'physicalStock'=>$bal['qty'],'totalReserved'=>$total,'globalAvailable'=>$global,'maxRemainingReservedQty'=>min($remaining,$current+$global),'suggestedRemainingReservedQty'=>0,'masterBlocked'=>$blocked]);}
        $byMat=[];foreach($contexts as $i=>$c)$byMat[$c['materialId']][]=$i;foreach($byMat as $idxs){usort($idxs,fn($a,$b)=>strcmp((string)$contexts[$a]['requiredDate'],(string)$contexts[$b]['requiredDate'])?:strcmp($contexts[$a]['productCode'],$contexts[$b]['productCode']));$pool=$contexts[$idxs[0]]['globalAvailable'];foreach($idxs as $i){$c=$contexts[$i];$base=min($c['currentRemainingReservedQty'],max($c['requiredQty']-$c['issuedQty']-$c['releasedQty'],0));$add=min(max($c['requiredQty']-$c['issuedQty']-$c['releasedQty']-$base,0),$pool);$contexts[$i]['suggestedRemainingReservedQty']=$base+$add;$pool-=$add;}}
        usort($contexts,fn($a,$b)=>strcmp($a['productCode'],$b['productCode'])?:strcmp($a['materialId'],$b['materialId']));return $contexts;
    }

    public function confirmReservations(string $email, array $p): array
    {
        $this->auth->require($email,['PROCUREMENT','PRODUCTION_MANAGER']);$execution=code($p['executionCode']??'');$client=s($p['clientRequestId']??'')?:uuid_id('REQ');$requested=(array)($p['lines']??[]);require_true($execution!==''&&(bool)$requested,'Thiếu BBSX hoặc dòng giữ tồn');return Database::transaction(function()use($email,$execution,$client,$requested){$du=$this->db->prepare('SELECT audit_id FROM audit_logs WHERE client_request_id=? AND action IN ("CONFIRM_RESERVATION","REALLOCATE_RESERVATION") LIMIT 1');$du->execute([$client]);if($du->fetch())return['idempotent'=>true,'clientRequestId'=>$client,'updated'=>0,'created'=>0,'context'=>$this->reservationContext($email,$execution)];$ctx=$this->reservationContext($email,$execution);$map=[];foreach($ctx as $c)$map[$c['requirementKey']]=$c;$changes=[];$positive=[];foreach($requested as $x){$key=s($x['requirementKey']??'');require_true(isset($map[$key]),'Không tìm thấy nhu cầu: '.$key);$c=$map[$key];require_true(!$c['masterBlocked'],'Mã vật tư trùng trong Master: '.$c['materialId'],'BLOCK_MASTER_DUPLICATE');$desired=n($x['remainingReservedQty']??0);require_true($desired>=0&&$desired<=$c['maxRemainingReservedQty']+1e-9,'Số lượng giữ vượt khả dụng','BLOCK_RESERVATION',409);$delta=$desired-$c['currentRemainingReservedQty'];$changes[]=['ctx'=>$c,'desired'=>$desired,'delta'=>$delta];if($delta>0)$positive[$c['materialId']]=($positive[$c['materialId']]??0)+$delta;}foreach($positive as $mat=>$sum){$base=array_values(array_filter($ctx,fn($x)=>$x['materialId']===$mat))[0]??null;require_true($sum<=n($base['globalAvailable']??0)+1e-9,'Tổng tăng giữ vượt tồn khả dụng: '.$mat,'BLOCK_RESERVATION',409);} $updated=0;$created=0;foreach($changes as $change){$c=$change['ctx'];$desired=$change['desired'];$st=$this->db->prepare('SELECT * FROM reservations WHERE requirement_key=? AND status<>"CANCELLED" FOR UPDATE');$st->execute([$c['requirementKey']]);$r=$st->fetch();$now=date('Y-m-d H:i:s');if($r){$issued=n($r['issued_qty']);$released=n($r['released_qty']);$confirmed=$issued+$released+$desired;$status=$desired<1e-9?($issued>0?'CLOSED':'CANCELLED'):($issued>0?'PARTIAL_ISSUED':'CONFIRMED');$this->db->prepare('UPDATE reservations SET confirmed_reserved_qty=?,remaining_reserved_qty=?,required_qty=?,suggested_reserved_qty=?,status=?,confirmed_by=?,confirmed_at=?,updated_at=NOW() WHERE reservation_id=?')->execute([$confirmed,$desired,$c['requiredQty'],$c['suggestedRemainingReservedQty'],$status,$email,$now,$r['reservation_id']]);$this->audit($email,'REALLOCATE_RESERVATION','RESERVATION',$r['reservation_id'],$client,'Cập nhật giữ tồn',(string)$c['currentRemainingReservedQty'],(string)$desired);$updated++;}elseif($desired>0){$id=uuid_id('RES');$this->db->prepare('INSERT INTO reservations(reservation_id,requirement_key,source_requirement_key,order_code,execution_code,product_code,material_id,required_qty,suggested_reserved_qty,confirmed_reserved_qty,remaining_reserved_qty,priority,required_date,status,confirmed_by,confirmed_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$c['requirementKey'],$c['sourceRequirementKey'],$c['orderCode'],$execution,$c['productCode'],$c['materialId'],$c['requiredQty'],$c['suggestedRemainingReservedQty'],$desired,$desired,1,$c['requiredDate']?:null,'CONFIRMED',$email,$now]);$this->audit($email,'CONFIRM_RESERVATION','RESERVATION',$id,$client,'Xác nhận giữ tồn','0',(string)$desired);$created++;}}
            return['idempotent'=>false,'clientRequestId'=>$client,'updated'=>$updated,'created'=>$created,'context'=>$this->reservationContext($email,$execution)];});
    }

    public function issue(string $email, array $p): array
    {
        $this->auth->require($email,['WAREHOUSE']);$execution=code($p['executionCode']??'');$date=date_ymd($p['issueDate']??null);$client=s($p['clientRequestId']??'')?:uuid_id('REQ');$lines=array_values(array_filter((array)($p['lines']??[]),fn($x)=>n($x['issueQty']??0)>0));require_true($execution&&$lines,'Thiếu BBSX hoặc dòng xuất');return Database::transaction(function()use($email,$execution,$date,$client,$lines,$p){$idem=$this->beginIdem($client,'ISSUE_POST',$email,$p);if($idem)return$idem;$seen=[];foreach($lines as $x){$id=s($x['reservationId']??'');require_true($id&&!isset($seen[$id]),'Reservation bị lặp','BLOCK_DUPLICATE_RESERVATION');$seen[$id]=1;}$in=implode(',',array_fill(0,count($seen),'?'));$st=$this->db->prepare("SELECT * FROM reservations WHERE reservation_id IN ($in) FOR UPDATE");$st->execute(array_keys($seen));$res=[];foreach($st->fetchAll()as$r)$res[$r['reservation_id']]=$r;require_true(count($res)===count($seen),'Có Reservation không tồn tại','RESERVATION_NOT_FOUND',404);$issueId=uuid_id('ISS');$codeDoc=$this->nextCode('ISSUE',$date);$this->db->prepare('INSERT INTO issues(issue_id,issue_code,issue_date,issue_type,order_code,execution_code,department,receiver,status,issued_by,posted_by,posted_at,client_request_id,note) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$issueId,$codeDoc,$date,$p['issueType']??'PRODUCTION',$p['orderCode']??$execution,$execution,$p['department']??'SẢN XUẤT',$p['receiver']??'','POSTED',$email,$email,date('Y-m-d H:i:s'),$client,$p['note']??'']);$out=[];$planned=[];foreach($lines as $x){$r=$res[s($x['reservationId'])];require_true(code($r['execution_code'])===$execution,'Reservation không thuộc BBSX đã chọn');$allow=$this->inventory->allowance($r['material_id'],$r['reservation_id'],true);$qty=n($x['issueQty']);$available=$allow['allowed']-($planned[$r['material_id']]??0);require_true($qty<=$allow['physical']+1e-9,'SL xuất lớn hơn tồn vật lý','BLOCK_AM_KHO',409);require_true($qty<=$available+1e-9,'SL xuất vượt phần khả dụng cho đơn này','BLOCK_RESERVATION_LIMIT',409);$remainingBom=max(n($r['required_qty'])-n($r['issued_qty']),0);$reason=s($x['varianceReason']??'');require_true($qty<=$remainingBom+1e-9||$reason!=='','Xuất vượt BOM nhưng thiếu lý do');$planned[$r['material_id']]=($planned[$r['material_id']]??0)+$qty;$lineId=uuid_id('IL');$m=$this->db->prepare('SELECT material_name,uom,item_class FROM materials WHERE material_id=? AND is_active=1');$m->execute([$r['material_id']]);$mat=$m->fetch();require_true((bool)$mat,'Không tìm thấy Mã vật tư','MATERIAL_NOT_FOUND',404);$b=$this->inventory->balance($r['material_id'],true);$movement=$this->inventory->movement(['ledger_id'=>'LG-'.$lineId,'transaction_date'=>$date,'transaction_type'=>'XUAT_SX','transaction_id'=>$issueId,'transaction_line_id'=>$lineId,'document_code'=>$codeDoc,'material_id'=>$r['material_id'],'qty_in'=>0,'qty_out'=>$qty,'unit_cost'=>$b['avg'],'order_code'=>$r['order_code'],'execution_code'=>$execution,'product_code'=>$r['product_code'],'created_by'=>$email,'client_request_id'=>$client]);$this->db->prepare('INSERT INTO issue_lines(issue_line_id,issue_id,issue_code,reservation_id,product_code,material_id,material_name_snapshot,uom_snapshot,bom_required_qty,previous_issued_qty,remaining_bom_qty,physical_stock_before,available_stock_before,issue_qty,management_unit_cost,management_amount,variance_vs_bom,variance_reason,note) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$lineId,$issueId,$codeDoc,$r['reservation_id'],$r['product_code'],$r['material_id'],$mat['material_name'],$mat['uom'],$r['required_qty'],$r['issued_qty'],$remainingBom,$allow['physical'],$available,$qty,$movement['unitCost'],$movement['amountOut'],max($qty-$remainingBom,0),$reason,$x['note']??'']);$newIssued=n($r['issued_qty'])+$qty;$remaining=max(n($r['confirmed_reserved_qty'])-$newIssued-n($r['released_qty']),0);$this->db->prepare('UPDATE reservations SET issued_qty=?,remaining_reserved_qty=?,status=? WHERE reservation_id=?')->execute([$newIssued,$remaining,$remaining<1e-9?'CLOSED':'PARTIAL_ISSUED',$r['reservation_id']]);$out[]=['issueLineId'=>$lineId,'materialId'=>$r['material_id'],'issueQty'=>$qty];}
            $this->audit($email,'POST_ISSUE','ISSUE',$issueId,$client,'POST hợp lệ','DRAFT','POSTED');$response=['issueId'=>$issueId,'issueCode'=>$codeDoc,'clientRequestId'=>$client,'lines'=>$out];$this->finishIdem($client,$response);return$response;});
    }

    public function returnMaterial(string $email, array $p): array
    {
        $this->auth->require($email,['WAREHOUSE']);$source=s($p['sourceIssueLineId']??'');$date=date_ymd($p['returnDate']??null);$qty=positive($p['returnQty']??0,'SL trả phải > 0');$usable=n($p['usableQty']??0);$scrap=n($p['scrapQty']??0);$client=s($p['clientRequestId']??'')?:uuid_id('REQ');require_true(abs($usable+$scrap-$qty)<1e-6,'SL usable + scrap phải bằng SL trả');return Database::transaction(function()use($email,$source,$date,$qty,$usable,$scrap,$client,$p){$idem=$this->beginIdem($client,'RETURN_POST',$email,$p);if($idem)return$idem;$st=$this->db->prepare('SELECT il.*,i.order_code,i.execution_code,i.status issue_status FROM issue_lines il JOIN issues i ON i.issue_id=il.issue_id WHERE il.issue_line_id=? FOR UPDATE');$st->execute([$source]);$src=$st->fetch();require_true((bool)$src,'Không tìm thấy dòng xuất nguồn','ISSUE_LINE_NOT_FOUND',404);require_true($src['issue_status']==='POSTED','Phiếu xuất nguồn chưa POSTED');$q=$this->db->prepare('SELECT COALESCE(SUM(return_qty),0) FROM production_returns WHERE source_issue_line_id=? AND status="POSTED"');$q->execute([$source]);require_true($qty<=n($src['issue_qty'])-n($q->fetchColumn())+1e-9,'Tổng SL trả vượt SL đã xuất','BLOCK_RETURN_OVER_ISSUED',409);$retId=uuid_id('RET');$codeDoc=$this->nextCode('RETURN',$date);$cost=n($src['management_unit_cost']);$this->db->prepare('INSERT INTO production_returns(return_id,return_code,return_date,source_issue_line_id,order_code,execution_code,product_code,material_id,return_qty,unit_cost,amount,return_condition,usable_stock_qty,scrap_qty,returned_by,received_by,status,posted_at,note,client_request_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$retId,$codeDoc,$date,$source,$src['order_code'],$src['execution_code'],$src['product_code'],$src['material_id'],$qty,$cost,$qty*$cost,$usable>0&&$scrap>0?'PARTIAL':($usable>0?'USABLE':'SCRAP'),$usable,$scrap,$p['returnedBy']??$email,$email,'POSTED',date('Y-m-d H:i:s'),$p['note']??'',$client]);if($usable>0)$this->inventory->movement(['ledger_id'=>'LG-'.$retId,'transaction_date'=>$date,'transaction_type'=>'TRA_SX','transaction_id'=>$retId,'transaction_line_id'=>$retId,'document_code'=>$codeDoc,'material_id'=>$src['material_id'],'qty_in'=>$usable,'qty_out'=>0,'unit_cost'=>$cost,'order_code'=>$src['order_code'],'execution_code'=>$src['execution_code'],'product_code'=>$src['product_code'],'created_by'=>$email,'client_request_id'=>$client]);$this->audit($email,'POST_RETURN','RETURN',$retId,$client,'POST hợp lệ','DRAFT','POSTED');$response=['returnId'=>$retId,'returnCode'=>$codeDoc,'clientRequestId'=>$client,'usableQty'=>$usable,'scrapQty'=>$scrap];$this->finishIdem($client,$response);return$response;});
    }

    public function adjustment(string $email, array $p): array
    {
        $this->auth->require($email,['PRODUCTION_MANAGER']);$material=code($p['materialId']??'');$type=code($p['adjustmentType']??'');$qty=positive($p['qty']??0,'SL điều chỉnh phải > 0');$reason=code($p['reasonCode']??'');$detail=s($p['reasonDetail']??'');$client=s($p['clientRequestId']??'')?:uuid_id('REQ');require_true(in_array($type,['IN','OUT'],true),'Loại điều chỉnh phải là IN hoặc OUT');require_true($reason&&$detail,'Phải chọn lý do và ghi diễn giải điều chỉnh');return Database::transaction(function()use($email,$material,$type,$qty,$reason,$detail,$client,$p){$idem=$this->beginIdem($client,'ADJUSTMENT_POST',$email,$p);if($idem)return$idem;$st=$this->db->prepare('SELECT * FROM materials WHERE material_id=? AND is_active=1');$st->execute([$material]);$m=$st->fetch();require_true((bool)$m,'Không tìm thấy Mã vật tư','MATERIAL_NOT_FOUND',404);require_true($m['item_class']==='STOCK','Chỉ điều chỉnh tồn cho vật tư STOCK');$before=$this->inventory->balance($material,true);require_true($type!=='OUT'||$qty<=$before['qty']+1e-9,'Tồn không đủ','BLOCK_AM_KHO',409);$cost=$type==='OUT'?$before['avg']:(n($p['unitCost']??0)?:$before['avg']);require_true($cost>=0&&($type!=='IN'||$cost>0),'Đơn giá điều chỉnh tăng phải > 0');$id=uuid_id('ADJ');$date=date_ymd($p['adjustmentDate']??null);$codeDoc=$this->nextCode('ADJUSTMENT',$date);$amount=$qty*$cost;$this->db->prepare('INSERT INTO adjustments(adjustment_id,adjustment_code,adjustment_date,material_id,adjustment_type,qty,unit_cost,amount,reason_code,reason_detail,requested_by,approved_by,status,posted_by,posted_at,note,client_request_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$codeDoc,$date,$material,$type,$qty,$cost,$amount,$reason,$detail,$email,$email,'POSTED',$email,date('Y-m-d H:i:s'),$p['note']??'',$client]);$this->inventory->movement(['ledger_id'=>'LG-'.$id,'transaction_date'=>$date,'transaction_type'=>$type==='IN'?'DIEU_CHINH_TANG':'DIEU_CHINH_GIAM','transaction_id'=>$id,'transaction_line_id'=>$id,'document_code'=>$codeDoc,'material_id'=>$material,'qty_in'=>$type==='IN'?$qty:0,'qty_out'=>$type==='OUT'?$qty:0,'unit_cost'=>$cost,'created_by'=>$email,'client_request_id'=>$client]);$this->audit($email,'POST_ADJUSTMENT','ADJUSTMENT',$id,$client,$detail,'',$type.' '.$qty);$response=['adjustmentId'=>$id,'adjustmentCode'=>$codeDoc,'materialId'=>$material,'qty'=>$qty,'type'=>$type];$this->finishIdem($client,$response);return$response;});
    }
}
